/**
 * If this is not called on a TikaInputStream, this detector
 * will spool up to this many bytes to a file to be detected
 * by the 'file' command.
 *
 * @param maxBytes
 */
public void setMaxBytes(int maxBytes) {
    this.maxBytes = maxBytes;
}
